// UnmarshalJSON decodes the known fields and collects the remaining keys into Values.
func (m *ScreenerScreenItem) UnmarshalJSON(b []byte) error {
	type plain ScreenerScreenItem
	if err := json.Unmarshal(b, (*plain)(m)); err != nil {
		return err
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(b, &raw); err != nil {
		return err
	}
	for _, k := range []string{"code", "matched"} {
		delete(raw, k)
	}
	m.Values = make(map[string]*float64, len(raw))
	for k, v := range raw {
		var x *float64
		if json.Unmarshal(v, &x) == nil { // tolerate unexpected value types
			m.Values[k] = x
		}
	}
	return nil
}

