// TradesListItem — Returned by Trades.List.
type TradesListItem struct {
	// Realized trade ID (use it with PATCH /trades/{id} and DELETE /trades)
	ID string `json:"id"`
	// Stock code
	Code string `json:"code"`
	// Two-letter broker code
	Broker string `json:"broker"`
	// Sell date; WIB wall-clock DateTime with a literal Z suffix (not UTC), e.g. 2026-10-16T00:00:00.000Z
	Date string `json:"date"`
	// Sold lots (1 lot = 100 shares)
	Lot int64 `json:"lot"`
	// Average buy price per share incl. buy fee at the time of the sale (Rupiah)
	BuyPrice float64 `json:"buy_price"`
	// Sell price per share (Rupiah)
	SellPrice float64 `json:"sell_price"`
	// lot x 100 x buy_price, rounded (Rupiah)
	BuyValue int64 `json:"buy_value"`
	// lot x 100 x sell_price, before sell fee (Rupiah)
	SellValue float64 `json:"sell_value"`
	// Realized profit/loss = sell_value - sell fee - buy_value, rounded (Rupiah)
	Net int64 `json:"net"`
	// (sell_price - buy_price) / buy_price x 100, 4 decimals (%)
	Percent float64 `json:"percent"`
	// PROFIT, LOSS or BEP (by net). One of: PROFIT, LOSS, BEP.
	Status string `json:"status"`
	// User note
	Note *string `json:"note"`
}

// TradesDeleteResponse — Returned by Trades.Delete.
type TradesDeleteResponse struct {
	// Confirmation message with the number of IDs sent, e.g. "2 trade deleted"
	Message string `json:"message"`
}

// TradesSummaryResponse — Returned by Trades.GetSummary.
type TradesSummaryResponse struct {
	// Stock codes ordered by number of realized trades, most frequent first
	TopCode []string `json:"top_code"`
	// Number of realized trades in the period
	TotalTransaction int64 `json:"total_transaction"`
	// Number of PROFIT trades
	TotalProfit int64 `json:"total_profit"`
	// Number of LOSS trades
	TotalLoss int64 `json:"total_loss"`
	// Number of BEP (break-even) trades
	TotalBep int64 `json:"total_bep"`
	// Sum of buy_value (Rupiah)
	TotalBuyValue float64 `json:"total_buy_value"`
	// Sum of sell_value (Rupiah)
	TotalSellValue float64 `json:"total_sell_value"`
	// Sum of net realized profit/loss (Rupiah)
	TotalNet float64 `json:"total_net"`
	// PROFIT trades / all trades (%)
	WinRate float64 `json:"win_rate"`
	// LOSS trades / all trades (%)
	LossRate float64 `json:"loss_rate"`
	// BEP trades / all trades (%)
	BepRate float64 `json:"bep_rate"`
	// Trade with the largest net profit
	TopWinValue TradesSummaryTopWinValue `json:"top_win_value"`
	// Trade with the largest net loss (most negative net)
	TopLossValue TradesSummaryTopLossValue `json:"top_loss_value"`
	// Trade with the best percent among PROFIT trades
	TopWinPercent TradesSummaryTopWinPercent `json:"top_win_percent"`
	// Trade with the worst percent among LOSS trades
	TopLossPercent TradesSummaryTopLossPercent `json:"top_loss_percent"`
}

// TradesSummaryTopWinValue — Trade with the largest net profit
type TradesSummaryTopWinValue struct {
	// Stock code (empty string when there is no such trade)
	Code string `json:"code"`
	// Largest net profit (Rupiah); 0 when there is no such trade
	Value float64 `json:"value"`
}

// TradesSummaryTopLossValue — Trade with the largest net loss (most negative net)
type TradesSummaryTopLossValue struct {
	// Stock code (empty string when there is no such trade)
	Code string `json:"code"`
	// Largest net loss (most negative net) (Rupiah); 0 when there is no such trade
	Value float64 `json:"value"`
}

// TradesSummaryTopWinPercent — Trade with the best percent among PROFIT trades
type TradesSummaryTopWinPercent struct {
	// Stock code (empty string when there is no such trade)
	Code string `json:"code"`
	// Best percent among PROFIT trades (%); 0 when there is no such trade
	Value float64 `json:"value"`
}

// TradesSummaryTopLossPercent — Trade with the worst percent among LOSS trades
type TradesSummaryTopLossPercent struct {
	// Stock code (empty string when there is no such trade)
	Code string `json:"code"`
	// Worst percent among LOSS trades (%); 0 when there is no such trade
	Value float64 `json:"value"`
}

